-- Hyprland config in Lua. Per-machine bits are in host.lua (generated by 03-post.sh),
-- the look (borders, gaps, rounding) in theme.lua (from the stowed theme).
-- Structure and look adapted from ad1822/hyprdots (MIT).
local home = os.getenv("HOME")
dofile(home .. "/.config/hypr/host.lua")
dofile(home .. "/.config/hypr/theme.lua")

-- Option (Alt) is the mod key. Cmd and Ctrl are swapped in kb_options so Cmd+C/V/T work like macOS.
local mod = "ALT"
local mods = "ALT + SHIFT"
local term = "kitty"
local menu = home .. "/.config/rofi/launcher.sh"

hl.config({
	input = {
		kb_options = "caps:escape,ctrl:swap_lwin_lctl,ctrl:swap_rwin_rctl",
		repeat_delay = 300,
		repeat_rate = 40,
		follow_mouse = 1,
		sensitivity = 0.3,
		touchpad = {
			natural_scroll = true,
			disable_while_typing = true,
			clickfinger_behavior = true,
		},
	},
	general = {
		layout = "scrolling",
		resize_on_border = true,
	},
	dwindle = { preserve_split = true },
	misc = {
		disable_hyprland_logo = true,
		disable_splash_rendering = true,
		force_default_wallpaper = 0,
	},
	xwayland = { force_zero_scaling = true },
})

hl.gesture({ fingers = 3, direction = "horizontal", action = "workspace" })

-- Short, light animations (set enabled = false for none)
hl.config({ animations = { enabled = true } })
hl.curve("easeOutQuint", { type = "bezier", points = { { 0.23, 1 }, { 0.32, 1 } } })
hl.curve("easeInOutCubic", { type = "bezier", points = { { 0.65, 0.05 }, { 0.36, 1 } } })
hl.animation({ leaf = "windows", enabled = true, speed = 4, bezier = "easeOutQuint" })
hl.animation({ leaf = "fade", enabled = true, speed = 4, bezier = "easeOutQuint" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 3, bezier = "easeInOutCubic", style = "slide" })

-- Autostart
hl.on("hyprland.start", function()
	hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
	hl.exec_cmd("hyprpaper")
	hl.exec_cmd("waybar")
	hl.exec_cmd("swayosd-server")
	hl.exec_cmd("nwg-dock-hyprland -d -ico launcher -i 40 -mb 8 -w 4 -hd 40 -c " .. menu)
	hl.exec_cmd("dunst")
	hl.exec_cmd("hypridle")
	hl.exec_cmd("gsettings set org.gnome.desktop.interface color-scheme prefer-dark")
	hl.exec_cmd("gsettings set org.gnome.desktop.interface gtk-theme Adwaita-dark")
	hl.exec_cmd("gsettings set org.gnome.desktop.interface icon-theme Mono")
end)

local function bind(modifier, key, cmd)
	hl.bind(modifier .. " + " .. key, hl.dsp.exec_cmd(cmd))
end

-- Apps and session
bind(mod, "Return", term)
bind(mod, "D", menu)
bind(mod, "B", "firefox")
bind(mod, "E", term .. " -e yazi")
hl.bind(mod .. " + Escape", hl.dsp.exit())
bind(mods, "E", home .. "/.config/rofi/powermenu.sh")
bind(mods, "C", "hyprctl reload")

-- Windows
hl.bind(mods .. " + Q", hl.dsp.window.close())
hl.bind(mod .. " + F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))
-- Minimize: send the window to a hidden workspace; Option+M shows that workspace to get it back.
hl.bind(mod .. " + N", hl.dsp.window.move({ workspace = "special:minimized", follow = false }))
hl.bind(mod .. " + M", hl.dsp.workspace.toggle_special("minimized"))
hl.bind(mods .. " + space", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mod .. " + equal", hl.dsp.layout("colresize +0.1"))
hl.bind(mod .. " + minus", hl.dsp.layout("colresize -0.1"))

-- Focus and move (vim keys and arrows, scrolling layout)
hl.bind(mod .. " + H", hl.dsp.layout("focus l"))
hl.bind(mod .. " + L", hl.dsp.layout("focus r"))
hl.bind(mod .. " + K", hl.dsp.layout("focus u"))
hl.bind(mod .. " + J", hl.dsp.layout("focus d"))
hl.bind(mod .. " + Left", hl.dsp.layout("focus l"))
hl.bind(mod .. " + Right", hl.dsp.layout("focus r"))
hl.bind(mod .. " + Up", hl.dsp.layout("focus u"))
hl.bind(mod .. " + Down", hl.dsp.layout("focus d"))
hl.bind(mods .. " + H", hl.dsp.layout("swapcol l"))
hl.bind(mods .. " + L", hl.dsp.layout("swapcol r"))
hl.bind(mods .. " + Left", hl.dsp.layout("swapcol l"))
hl.bind(mods .. " + Right", hl.dsp.layout("swapcol r"))

-- Workspaces: Option+n goes to n (again: back), Option+Shift+n sends the window
for i = 1, 9 do
	local ws = tostring(i)
	hl.bind(mod .. " + " .. ws, function()
		local current = hl.get_active_workspace()
		if current ~= nil and current.id == i then
			hl.dispatch(hl.dsp.focus({ workspace = "previous" }))
		else
			hl.dispatch(hl.dsp.focus({ workspace = ws }))
		end
	end)
	hl.bind(mods .. " + " .. ws, hl.dsp.window.move({ workspace = ws }))
end
hl.bind(mod .. " + Tab", hl.dsp.focus({ workspace = "previous" }))
hl.bind(mod .. " + period", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mod .. " + comma", hl.dsp.focus({ workspace = "e-1" }))

-- Mouse: Option + drag moves, Option + right-drag resizes
hl.bind(mod .. " + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(mod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Screenshots
hl.bind("Print", hl.dsp.exec_cmd(home .. "/.local/bin/shot"))
hl.bind("SHIFT + Print", hl.dsp.exec_cmd(home .. "/.local/bin/shot save"))
bind(mods, "S", home .. "/.local/bin/shot")

-- Media and brightness keys (Apple keyboard; fnmode=1 makes them the default)
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("swayosd-client --output-volume raise"), { repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("swayosd-client --output-volume lower"), { repeating = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("swayosd-client --output-volume mute-toggle"))
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("swayosd-client --input-volume mute-toggle"))
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd(home .. "/.local/bin/osd-brightness up"), { repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd(home .. "/.local/bin/osd-brightness down"), { repeating = true })
hl.bind("XF86KbdBrightnessUp", hl.dsp.exec_cmd(home .. "/.local/bin/osd-brightness up kbd"), { repeating = true })
hl.bind("XF86KbdBrightnessDown", hl.dsp.exec_cmd(home .. "/.local/bin/osd-brightness down kbd"), { repeating = true })
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("swayosd-client --playerctl play-pause"))
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("swayosd-client --playerctl next"))
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("swayosd-client --playerctl prev"))

-- Title bars with close and minimize buttons, for mouse use (hyprbars plugin; skipped if not installed).
-- The plugin must match the Hyprland version: rebuild it after a Hyprland update.
local bars_lib = "/usr/lib/libhyprbars.so"
local bars_file = io.open(bars_lib)
if bars_file then
	bars_file:close()
	local t = bar_theme or { bar = "rgb(0a0a0a)", text = "rgb(ffffff)", close = "rgb(ffffff)", min = "rgb(8a8a8a)", icon = "rgb(0a0a0a)" }
	-- Never load the plugin while the config is being read: a plugin load re-reads the config, and
	-- loading it again from here loops until Hyprland crashes. It is loaded once from the autostart
	-- below; that re-read then finds the plugin and applies the settings.
	if not hl.plugin.hyprbars then
		hl.on("hyprland.start", function()
			hl.exec_cmd("hyprctl plugin load " .. bars_lib)
		end)
	end
	if hl.plugin.hyprbars then
		hl.config({
			plugin = {
				hyprbars = {
					bar_height = 22,
					bar_color = t.bar,
					["col.text"] = t.text,
					bar_text_size = 10,
					bar_text_font = "Inter",
					bar_buttons_alignment = "left",
					bar_padding = 8,
					bar_button_padding = 7,
					bar_part_of_window = true,
					bar_precedence_over_border = true,
				},
			},
		})
		hl.plugin.hyprbars.add_button({ bg_color = t.close, fg_color = t.icon, size = 13, icon = "x", action = "hyprctl dispatch 'hl.dsp.window.close()'" })
		hl.plugin.hyprbars.add_button({ bg_color = t.min, fg_color = t.icon, size = 13, icon = "-", action = "hyprctl dispatch 'hl.dsp.window.move({ workspace = \"special:minimized\", follow = false })'" })
	end
end
